import{_ as o,o as t,c as n,a5 as e}from"./chunks/framework.BEZBAInb.js";const k=JSON.parse('{"title":"마스코트 Kona","description":"","frontmatter":{"title":"마스코트 Kona","order":2},"headers":[],"relativePath":"ko/latest/community/kona.md","filePath":"ko/latest/community/kona.md","lastUpdated":1788455378000}'),r={name:"ko/latest/community/kona.md"};function i(l,a,s,c,d,p){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="주변-ip-소개" tabindex="-1">주변 IP 소개 <a class="header-anchor" href="#주변-ip-소개" aria-label="Permalink to &quot;주변 IP 소개&quot;">​</a></h1><h2 id="kona-소개" tabindex="-1">Kona 소개 <a class="header-anchor" href="#kona-소개" aria-label="Permalink to &quot;Kona 소개&quot;">​</a></h2><p>Kona는 Konado의 전용 마스코트입니다. <strong>발랄하고 사랑스러우며 활기찬</strong> 소녀 이미지를 중심으로 하며, 브랜드 비주얼의 중요한 상징일 뿐 아니라 사용자와 Konado를 친근하게 이어 주는 매개체이기도 합니다.</p><h2 id="kona-이미지" tabindex="-1">Kona 이미지 <a class="header-anchor" href="#kona-이미지" aria-label="Permalink to &quot;Kona 이미지&quot;">​</a></h2><p>Kona는 Konado의 다양한 장면에 등장합니다. 시작 화면, 공식 웹사이트 메인 페이지, 제품 문서 어디에서나 Kona의 이미지는 브랜드에 생동감을 더합니다. Konado의 버전이 발전함에 따라 Kona의 모습도 함께 진화하며, 새 버전의 디자인 스타일에 맞추는 동시에 세부 표현을 다듬어 더 세련되고 식별하기 쉬운 이미지가 됩니다.</p><p>일반적으로 Konado의 <strong>주요 버전 업데이트</strong> 때는 Kona의 새로운 전용 이미지가 공개됩니다. 각 이미지는 고유한 디자인 아이디어를 담고 있으며, Kona의 핵심 분위기를 이어 가면서 제품에 더 많은 재미와 기억에 남는 요소를 더합니다.</p><p>물론 작은 버전 업데이트에서도 계절 의상으로 바뀌거나 작은 장식이 추가되는 등 Kona에게 작은 변화가 생길 수 있습니다. 이를 통해 이미지가 더 풍부하고 다양해집니다.</p><blockquote><p>일러스트레이터: <a href="https://github.com/ioniccrystal" target="_blank" rel="noreferrer">ioniccrystal</a> 공개일: 2025-09-15</p></blockquote><p align="center"><img src="https://legacy.godothub.com/kbgirl/kona/kona.png" alt="Kona 2.0 메인 이미지" width="300"></p>',9)])])}const _=o(r,[["render",i]]);export{k as __pageData,_ as default};
